package com.srent.storage;
import com.srent.config.AppProperties;import io.minio.*;import lombok.RequiredArgsConstructor;import org.springframework.boot.ApplicationArguments;import org.springframework.boot.ApplicationRunner;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.stereotype.Component;
@Component @ConditionalOnProperty(name="app.storage.initialize",havingValue="true",matchIfMissing=true) @RequiredArgsConstructor
public class StorageInitializer implements ApplicationRunner{private final MinioClient minio;private final AppProperties props;@Override public void run(ApplicationArguments args)throws Exception{var s=props.getStorage();create(s.getPublicBucket());create(s.getPrivateBucket());String policy="{\"Version\":\"2012-10-17\",\"Statement\":[{\"Effect\":\"Allow\",\"Principal\":{\"AWS\":[\"*\"]},\"Action\":[\"s3:GetBucketLocation\",\"s3:ListBucket\"],\"Resource\":[\"arn:aws:s3:::"+s.getPublicBucket()+"\"]},{\"Effect\":\"Allow\",\"Principal\":{\"AWS\":[\"*\"]},\"Action\":[\"s3:GetObject\"],\"Resource\":[\"arn:aws:s3:::"+s.getPublicBucket()+"/*\"]}]}";minio.setBucketPolicy(SetBucketPolicyArgs.builder().bucket(s.getPublicBucket()).config(policy).build());}private void create(String b)throws Exception{if(!minio.bucketExists(BucketExistsArgs.builder().bucket(b).build()))minio.makeBucket(MakeBucketArgs.builder().bucket(b).build());}}
